CREATE VIEW "public"."product_rating_stats" AS (select "products"."id" as "product_id", round(avg("reviews"."rating")::numeric, 1) as "rating_avg", count("reviews"."id")::int as "rating_count", (count("reviews"."id") filter (where "reviews"."rating" = 1))::int as "rating_1", (count("reviews"."id") filter (where "reviews"."rating" = 2))::int as "rating_2", (count("reviews"."id") filter (where "reviews"."rating" = 3))::int as "rating_3", (count("reviews"."id") filter (where "reviews"."rating" = 4))::int as "rating_4", (count("reviews"."id") filter (where "reviews"."rating" = 5))::int as "rating_5" from "products" left join "reviews" on "reviews"."product_id" = "products"."id" group by "products"."id");